# 割り込みセーフ SPSC リングバッファ（C言語）

## 設計方針

| 要素 | 方針 |
|------|------|
| 容量 | 2 の冪乗（マスク演算で剰余を高速化） |
| インデックス | 各側が自分のインデックスのみ更新 → アトミック不要 |
| 可視性 | `volatile` + メモリバリア（DMB）で順序保証 |
| 割り込み | 割り込み側がプロデューサ、メインループがコンシューマ（逆も可） |

---

## 1. `ring_buffer.h`

```c
#ifndef RING_BUFFER_H
#define RING_BUFFER_H

#include <stdint.h>
#include <stddef.h>

/* ===== 設定 ===== */
#ifndef RING_CAPACITY
#define RING_CAPACITY  256u   /* 必ず 2 の冪乗にする */
#endif

#if (RING_CAPACITY & (RING_CAPACITY - 1)) != 0
#error "RING_CAPACITY must be a power of 2"
#endif

#define RING_MASK  (RING_CAPACITY - 1)

/* ===== メモリバリア ===== */
/* ARM Cortex-M (CMSIS) では __DMB() が最適。それ以外はコンパイラバリア。 */
#if defined(__ARM_ARCH)
  #define RING_DMB()  __DMB()
#else
  #define RING_DMB()  __asm__ volatile("" ::: "memory")
#endif

/* ===== 型定義 ===== */
typedef struct {
    volatile uint32_t write_pos;   /* プロデューサのみ更新 */
    uint8_t           buffer[RING_CAPACITY];
    volatile uint32_t read_pos;    /* コンシューマのみ更新 */
} ring_buffer_t;

/* ===== API ===== */

/** バッファを初期化（ゼロクリア） */
void ring_init(ring_buffer_t *rb);

/** データ1バイト押し込み。満杯なら 0 を返す。 */
int ring_push(ring_buffer_t *rb, uint8_t data);

/** データ1バイト取り出し。空なら 0 を返す。 */
int ring_pop(ring_buffer_t *rb, uint8_t *out);

/** 現在の格納バイト数 */
uint32_t ring_count(const ring_buffer_t *rb);

/** 空き容量 */
uint32_t ring_free(const ring_buffer_t *rb);

/** 満杯か */
static inline int ring_full(const ring_buffer_t *rb) {
    return (rb->write_pos - rb->read_pos) == RING_CAPACITY;
}

/** 空か */
static inline int ring_empty(const ring_buffer_t *rb) {
    return (rb->write_pos == rb->read_pos);
}

#endif /* RING_BUFFER_H */
```

