## 2. `ring_buffer.c`

```c
#include "ring_buffer.h"
#include <string.h>

void ring_init(ring_buffer_t *rb)
{
    rb->write_pos = 0;
    /* read_pos は構造体末尾。構造体全体をゼロクリア */
    memset(rb, 0, sizeof(*rb));
}

int ring_push(ring_buffer_t *rb, uint8_t data)
{
    uint32_t wp = rb->write_pos;

    /* 満杯チェック（read_pos を見て判断） */
    if ((wp - rb->read_pos) == RING_CAPACITY) {
        return 0;   /* 失敗 */
    }

    /* 1) バリア: バッファ書き込みがインデックス更新より前に見えるように */
    RING_DMB();

    /* 2) データ書き込み */
    rb->buffer[wp & RING_MASK] = data;

    /* 3) バリア: データ書き込みがインデックス更新より前に見えるように */
    RING_DMB();

    /* 4) インデックス更新（書き込み完了） */
    rb->write_pos = wp + 1;

    return 1;   /* 成功 */
}

int ring_pop(ring_buffer_t *rb, uint8_t *out)
{
    uint32_t rp = rb->read_pos;

    /* 空チェック（write_pos を見て判断） */
    if (rp == rb->write_pos) {
        return 0;   /* 失敗 */
    }

    /* 1) バリア: インデックス更新がデータ読み出しより前に見えるように */
    RING_DMB();

    /* 2) データ読み出し */
    *out = rb->buffer[rp & RING_MASK];

    /* 3) バリア: データ読み出しがインデックス更新より前に完了 */
    RING_DMB();

    /* 4) インデックス更新 */
    rb->read_pos = rp + 1;

    return 1;   /* 成功 */
}

uint32_t ring_count(const ring_buffer_t *rb)
{
    return rb->write_pos - rb->read_pos;
}

uint32_t ring_free(const ring_buffer_t *rb)
{
    return RING_CAPACITY - ring_count(rb);
}
```

