## 3. `example.c`（使用例）

```c
#include <stdio.h>
#include "ring_buffer.h"

/*
 * 例: 割り込み（擬似）がデータを送り、メインループが受ける。
 * 実際の MCU では UART RX 割り込みハンドラ内で ring_push() を呼ぶ。
 */

/* 擬似割り込みハンドラ（実機では UART_RX_IRQHandler 等） */
void fake_isr(void)
{
    static uint8_t counter = 0;
    ring_push(&g_ring, counter++);
}

ring_buffer_t g_ring;

int main(void)
{
    ring_init(&g_ring);

    printf("Ring capacity: %u bytes\n", RING_CAPACITY);

    /* --- 10 バイト送信（プロデューサ側の役割） --- */
    for (int i = 0; i < 10; i++) {
        fake_isr();
    }
    printf("After push: count = %u\n", ring_count(&g_ring));

    /* --- 全バイト受領（コンシューマ側の役割） --- */
    uint8_t val;
    int n = 0;
    while (ring_pop(&g_ring, &val)) {
        printf("  pop[%d] = %u\n", n++, val);
    }
    printf("After drain: count = %u, empty = %d\n",
           ring_count(&g_ring), ring_empty(&g_ring));

    /* --- ラップアラウンド確認 --- */
    printf("\n--- Wrap-around test ---\n");
    for (int i = 0; i < (int)RING_CAPACITY + 5; i++) {
        fake_isr();
    }
    printf("Wrapped count (mod): %u\n", ring_count(&g_ring));

    return 0;
}
```

